SELECT DISTINCT u.id, u.user_id, u.username, u.nickname, u.email, u.phone, u.password, u.auth_provider, u.avatar, u.status, u.create_time, u.update_time FROM ai_user u INNER JOIN ai_user_role ur ON ur.user_id = u.user_id INNER JOIN ai_role r ON r.role_id = ur.role_id WHERE COALESCE(u.auth_provider, '') != 'MT_H5' AND r.status = 1 AND r.role_code = #{roleCode}
AND (u.user_id LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY u.create_time DESC

